entries.syntax_block:
Profile = New InternetMailProfile();
Profile.SMTPServerAddress = server;
Profile.SecureConnection = New SecureConnection();

entries.example:
Profile = New InternetMailProfile();
Profile.SMTPServerAddress = "smtp.example.com";
Profile.SMTPUser = "shop@example.com";
Profile.SMTPPassword = Password;
Profile.SecureConnection = New SecureConnection();   // TLS on 465

Message = New InternetMailMessage();
Message.From = "Shop <shop@example.com>";
Message.To.Add("buyer@example.net");
Message.Subject = "Invoice 42";
Message.Texts.Add("The invoice is attached.");
Message.Attachments.Add("C:\out\invoice-42.pdf");

Mail = New InternetMail();
Mail.Logon(Profile);
Mail.Send(Message);
Mail.Logoff();

